async function e(){try{const t=await fetch("/api/wiki/health");if(!t.ok)return null;const a=await t.json();return a.ok&&a.health?a.health:null}catch{return null}}async function i(){const t=await fetch("/api/wiki/semantic-search");if(t.status===404)return null;if(!t.ok)throw new Error(`HTTP ${t.status} ${t.statusText}`);return await t.json()}async function n(t){const a=await fetch("/api/wiki/semantic-search",{method:"PUT",headers:{"Content-Type":"application/json"},body:JSON.stringify({enabled:t})});if(!a.ok)throw new Error(`HTTP ${a.status} ${a.statusText}`);return await a.json()}async function s(){const t=await fetch("/api/wiki/reindex",{method:"POST"});if(!t.ok)throw new Error(`HTTP ${t.status} ${t.statusText}`);return await t.json()}export{i as a,e as f,s as r,n as s};
